settings.global_custom_css:
#addonId {
  transition: background-position 0.4s ease;
}
#addonId:hover{
  background-position: calc(156% + 20px) calc(252% + 20px);

}
#addonId .sppb-btn {
  width: 100% !important;
}

#addonId .sppb-addon-title {
  display: flex;
  align-items: center;
  gap: 15px;

}
#addonId .sppb-addon-title > span {
  font-size: 20px !important;
  transition: all 0.5s ease;

}

#addonId .sppb-addon-title:hover > span {
    transform: translateX(10px);
  transition: all 0.5s ease;
}

#addonId .sppb-addon-title {
    display: flex;
    justify-content: space-between;
    align-items: center;
    opacity: 0.1;
}
